def search_algorithm(src, dsts, G, num_partitions):
    """
    Approach: global Steiner-tree multicast. Build a collapsed undirected view S
    of G where each pair's weight is the min cost over parallel directed edges
    (None-cost edges treated as free, matching make_nx_graph's unpriced pairs).
    Run steiner_tree(S, [src]+dsts) so expensive trunk edges near the source are
    shared across destinations instead of paid once per dst (per partition).
    Expand each destination's unique tree path from src into directed hops using
    the cheapest real directed edge of G for each consecutive pair, appending
    [s, t, edge_data] per partition exactly like the incumbent. Per-dst Dijkstra
    fallback preserves validity if the tree route is incomplete.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def dijkstra_route(dst):
        """Incumbent per-dst Dijkstra fallback; appends and returns True on success."""
        try:
            path = nx.dijkstra_path(h, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NetworkXException):
            return False
        for i in range(len(path) - 1):
            s, t = path[i], path[i + 1]
            for j in range(bc_topology.num_partitions):
                bc_topology.append_dst_partition_path(dst, j, [s, t, G[s][t]])
        return True

    # Directed view with None costs treated as free (used for all routing
    # decisions and cost simulation).
    W = nx.DiGraph()
    for u, v, data in h.edges(data=True):
        c = data.get("cost")
        W.add_edge(u, v, cost=0.0 if c is None else c)

    inf = float("inf")

    def sp_cost(paths):
        """Simulated cost: each distinct directed edge in the union of paths
        is charged exactly once (preserves the sharing benefit)."""
        seen = set()
        total = 0.0
        for p in paths:
            for i in range(len(p) - 1):
                e = (p[i], p[i + 1])
                if e not in seen:
                    seen.add(e)
                    total += W[p[i]][p[i + 1]]["cost"]
        return total

    def splice(a, b):
        """Concatenate two node paths sharing their junction node."""
        return a + b[1:]

    reachable = [d for d in dsts if d in W and nx.has_path(W, src, d)]
    if not reachable:
        for dst in dsts:
            dijkstra_route(dst)
        return bc_topology

    # ---- Candidate A: directed shortest-path-heuristic (SPH) Steiner ----
    # The undirected collapse of the parent minimizes min(c(u,v), c(v,u)) per
    # pair, which misprices asymmetric directed costs (common in cloud egress
    # pricing) and can yield expensive or invalid directed expansions. Directed
    # SPH instead grows an arborescence in the true directed metric W: keep a
    # partial set of tree nodes/edges, run a multi-source Dijkstra with all
    # current tree nodes at distance 0, attach the cheapest unplaced terminal
    # via its winning path (real directed edges only), and repeat. Multistart
    # over R=10 deterministic terminal orderings: ascending, descending src
    # distance, and 8 hash-shuffled orders (each start strictly bounded by
    # |T| Dijkstra sweeps; no unbounded iteration).
    def sph(terminal_order):
        """Grow a directed arborescence rooted at src; return its directed
        edge set, or None if a terminal is unreachable from the tree."""
        T_nodes = {src}
        T_edges = set()
        order = list(terminal_order)
        while order:
            dist = {n: 0.0 for n in T_nodes}
            prev = {}
            pq = [(0.0, n) for n in T_nodes]
            heapq.heapify(pq)
            while pq:
                d, u = heapq.heappop(pq)
                if d > dist.get(u, inf):
                    continue
                for v, ed in W[u].items():
                    nd = d + ed["cost"]
                    if nd < dist.get(v, inf) - 1e-12:
                        dist[v] = nd
                        prev[v] = u
                        heapq.heappush(pq, (nd, v))
            best_t, best_d = None, inf
            for t in order:
                d = dist.get(t, inf)
                if d < best_d:
                    best_t, best_d = t, d
            if best_t is None:
                return None
            v = best_t
            while v not in T_nodes:
                u = prev[v]
                T_edges.add((u, v))
                v = u
            T_nodes.add(best_t)
            order.remove(best_t)
        return T_edges

    def routes_from_edges(edges):
        """Build per-dst src paths from a directed edge set; verify hops;
        return routes dict or None if any dst is missing/invalid."""
        succ = {}
        for u, v in edges:
            succ.setdefault(u, []).append(v)
        tree_paths = {src: [src]}
        queue = [src]
        while queue:
            u = queue.pop(0)
            for w in succ.get(u, []):
                if w not in tree_paths:
                    tree_paths[w] = tree_paths[u] + [w]
                    queue.append(w)
        routes = {}
        for dst in reachable:
            if dst not in tree_paths:
                return None
            p = tree_paths[dst]
            if not all(h.has_edge(p[i], p[i + 1]) for i in range(len(p) - 1)):
                return None
            routes[dst] = p
        return routes

    tree_routes = None
    tree_cost = inf
    if len(reachable) > 1:
        try:
            src_dist = {d: nx.dijkstra_path_length(W, src, d) for d in reachable}
        except nx.NetworkXException:
            src_dist = {d: inf for d in reachable}
        # R=10 deterministic orderings (no more starts than the parent ran).
        orders = [
            sorted(reachable, key=str),
            sorted(reachable, key=lambda d: (src_dist.get(d, inf), str(d))),
        ]
        for r in range(8):
            salt = r + 1

            def hkey(d, _s=salt):
                hv = 2166136261
                for ch in str(d) + "|" + str(_s):
                    hv = ((hv ^ ord(ch)) * 16777619) & 0xFFFFFFFF
                return (hv % 1000003, str(d))

            orders.append(sorted(reachable, key=hkey))
        for order in orders:
            edges = sph(order)
            if edges is None:
                continue
            r_routes = routes_from_edges(edges)
            if r_routes is None:
                continue
            c = sp_cost(list(r_routes.values()))
            if c < tree_cost:
                tree_cost = c
                tree_routes = r_routes

    # ---- Candidate B: hub-replication two-stage trunk ----
    # Rank dsts by total directed distance to all other dsts; take the most
    # central 3; collect nodes on their shortest src->dst paths as hubs.
    def centrality(d):
        tot = 0.0
        for o in reachable:
            if o == d:
                continue
            try:
                tot += nx.dijkstra_path_length(W, d, o)
            except nx.NetworkXException:
                return inf
        return tot

    # Precompute shortest paths between all relevant pairs ONCE. Hub evaluation
    # then costs only path concatenation, which makes exhaustive single-hub
    # (every node) and two-hub chain (src->h1->h2->dsts) search affordable —
    # strictly dominating the old top-3-centrality heuristic.
    nodes = [n for n in W.nodes if n != src]
    pair_path = {}
    for a in [src] + nodes:
        for b in nodes:
            if a == b:
                continue
            try:
                if nx.has_path(W, a, b):
                    pair_path[(a, b)] = nx.dijkstra_path(W, a, b)
            except nx.NetworkXException:
                pass

    hub_routes = None
    hub_cost = inf

    def eval_hubs(chain):
        """Evaluate trunk src->chain[0]->chain[1]->...->dsts using precomputed
        pair paths. Returns (full per-dst paths, union cost) or (None, inf)."""
        in_path = [src]
        for h in chain:
            if (in_path[-1], h) not in pair_path:
                return None, inf
            in_path = splice(in_path, pair_path[(in_path[-1], h)])
        out_paths = {}
        for d in reachable:
            if (in_path[-1], d) not in pair_path:
                return None, inf
            out_paths[d] = splice(in_path, pair_path[(in_path[-1], d)])
        return out_paths, sp_cost([in_path] + list(out_paths.values()))

    # Single-hub: every node. Two-hub chains: bounded to keep compute small
    # (first-stage hubs limited to the 25 most central nodes if graph is big).
    two_stage = nodes
    if len(nodes) > 25:
        two_stage = sorted(nodes, key=centrality)[:25]
    for u in nodes:
        out_paths, c = eval_hubs([u])
        if out_paths is not None and c < hub_cost:
            hub_cost = c
            hub_routes = out_paths
    for u in two_stage:
        for v in nodes:
            if u == v:
                continue
            out_paths, c = eval_hubs([u, v])
            if out_paths is not None and c < hub_cost:
                hub_cost = c
                hub_routes = out_paths

    # ---- Candidate C: SPT seed (union of per-dst shortest paths) ----
    # Structurally distinct from the Steiner tree (forced sharing) and the hub
    # trunk (forced relay): the SPT gives each dst its individually cheapest
    # path (maximal fan-out). Hill-climbing from it lets the search *add*
    # sharing incrementally — a basin the shared Steiner start cannot reach.
    spt_routes = None
    spt_cost = inf
    if all((src, d) in pair_path for d in reachable):
        spt_routes = {}
        for d in reachable:
            p = pair_path[(src, d)]
            if all(h.has_edge(p[i], p[i + 1]) for i in range(len(p) - 1)):
                spt_routes[d] = p
            else:
                spt_routes = None
                break
        if spt_routes is not None:
            spt_cost = sp_cost(list(spt_routes.values()))

    # ---- Best-of-seeds local search ----
    # The hill-climb runs independently from each surviving seed (tree, hub,
    # SPT); the argmin of sp_cost is committed. Monotone: the tree seed starts
    # from the incumbent's committed structure and cost never increases, so
    # the result can only match or beat it. Two move types per sweep:
    #   (1) marginal-cost Dijkstra substitution (E-edges priced 0),
    #   (2) cross-path splicing: reuse a prefix of another dst's path plus a
    #       precomputed shortest suffix from the junction — this can create
    #       NEW shared edges that the marginal Dijkstra view cannot propose.
    # Bounded plateau moves (equal total cost) are accepted up to a small
    # budget per sweep to traverse plateaus; cost is never increased.
    def local_search(seed_routes):
        """Hill-climb with marginal-cost Dijkstra + cross-path splice moves;
        accepts strictly-improving and (budgeted) equal-cost moves only."""
        paths = {d: list(seed_routes[d]) for d in seed_routes}
        cur = sp_cost(list(paths.values()))
        for _sweep in range(3):
            E = set()
            for p in paths.values():
                for i in range(len(p) - 1):
                    E.add((p[i], p[i + 1]))
            M = nx.DiGraph()
            for u, v, data in W.edges(data=True):
                M.add_edge(u, v, cost=0.0 if (u, v) in E else data["cost"])
            improved = False
            plateau = 0
            for dst in list(paths):
                # Move 1: marginal-cost Dijkstra substitution.
                try:
                    cand = nx.dijkstra_path(M, src, dst, weight="cost")
                except nx.NetworkXException:
                    cand = None
                if cand is not None and cand != paths[dst]:
                    trial = dict(paths)
                    trial[dst] = cand
                    tc = sp_cost(list(trial.values()))
                    if tc < cur - 1e-12 or (tc <= cur + 1e-12 and plateau < 4):
                        if tc <= cur + 1e-12 and tc > cur - 1e-12:
                            plateau += 1
                        paths = trial
                        cur = tc
                        improved = True
                # Move 2: cross-path splice (share a prefix of another path).
                for o, op in list(paths.items()):
                    if o == dst:
                        continue
                    for k in range(1, len(op)):
                        j = op[k]
                        if (j, dst) not in pair_path:
                            continue
                        cand2 = op[: k + 1] + pair_path[(j, dst)][1:]
                        if cand2 == paths[dst]:
                            continue
                        if not all(
                            h.has_edge(cand2[i], cand2[i + 1])
                            for i in range(len(cand2) - 1)
                        ):
                            continue
                        trial = dict(paths)
                        trial[dst] = cand2
                        tc = sp_cost(list(trial.values()))
                        if tc < cur - 1e-12 or (tc <= cur + 1e-12 and plateau < 4):
                            if tc <= cur + 1e-12 and tc > cur - 1e-12:
                                plateau += 1
                            paths = trial
                            cur = tc
                            improved = True
            if not improved:
                break
        return paths, cur

    seeds = []
    if tree_routes is not None:
        seeds.append(tree_routes)
    if hub_routes is not None:
        seeds.append(hub_routes)
    if spt_routes is not None:
        seeds.append(spt_routes)

    if not seeds:
        for dst in dsts:
            dijkstra_route(dst)
        return bc_topology

    best_paths = None
    best_cost = inf
    for seed in seeds:
        p, c = local_search(seed)
        if c < best_cost:
            best_cost = c
            best_paths = p
    routes = best_paths

    for dst in dsts:
        if dst in routes:
            tpath = routes[dst]
            for i in range(len(tpath) - 1):
                s, t = tpath[i], tpath[i + 1]
                for j in range(bc_topology.num_partitions):
                    bc_topology.append_dst_partition_path(dst, j, [s, t, h[s][t]])
        else:
            dijkstra_route(dst)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


